const express = require('express');
const axios = require('axios');
const AWS = require('aws-sdk');

const app = express();
app.use(express.json());

// Internal service discovery endpoint
// Fetches health status from microservices by URL
app.post('/api/v1/service-check', async (req, res) => {
  const { serviceUrl, timeout } = req.body;

  if (!serviceUrl) {
    return res.status(400).json({ error: 'serviceUrl is required' });
  }

  // Basic validation - ensure it looks like a URL
  try {
    new URL(serviceUrl);
  } catch (e) {
    return res.status(400).json({ error: 'Invalid URL format' });
  }

  // Block obvious localhost references
  const parsed = new URL(serviceUrl);
  if (parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1') {
    return res.status(403).json({ error: 'Localhost access denied' });
  }

  try {
    const response = await axios.get(serviceUrl, {
      timeout: timeout || 5000,
      maxRedirects: 3,
      validateStatus: () => true
    });

    // If response contains AWS credentials, use them to describe the instance
    let instanceInfo = null;
    if (response.data && typeof response.data === 'object' && response.data.AccessKeyId) {
      const sts = new AWS.STS({
        accessKeyId: response.data.AccessKeyId,
        secretAccessKey: response.data.SecretAccessKey,
        sessionToken: response.data.Token
      });
      try {
        instanceInfo = await sts.getCallerIdentity().promise();
      } catch (stsErr) {
        instanceInfo = { error: 'Could not verify identity' };
      }
    }

    return res.json({
      status: response.status,
      headers: response.headers,
      body: typeof response.data === 'string' ? response.data.substring(0, 2048) : response.data,
      instanceInfo
    });
  } catch (error) {
    return res.status(502).json({
      error: 'Service unreachable',
      details: error.message
    });
  }
});

// Webhook registration - fetches URL to validate it's alive
app.post('/api/v1/webhooks/register', async (req, res) => {
  const { callbackUrl, events } = req.body;

  if (!callbackUrl || !events || !Array.isArray(events)) {
    return res.status(400).json({ error: 'callbackUrl and events[] required' });
  }

  // Validate the callback URL is reachable
  try {
    const validation = await axios.post(callbackUrl, {
      challenge: Math.random().toString(36).substring(7)
    }, { timeout: 3000 });

    if (validation.status >= 200 && validation.status < 300) {
      return res.json({ registered: true, id: Math.random().toString(36).substring(7) });
    }
    return res.status(400).json({ error: 'Callback URL did not respond successfully' });
  } catch (err) {
    return res.status(400).json({ error: 'Callback URL unreachable', details: err.message });
  }
});

app.listen(3000, () => {
  console.log('Service mesh gateway running on :3000');
});
